mapper.select:
SELECT o.id, o.order_no AS orderNo, o.user_id AS userId, o.amount, o.package_id AS packageId, o.provide_amount AS provideAmount, o.pay_status AS payStatus, o.pay_way AS payWay, o.pay_time AS payTime, o.subject, o.body, o.create_time AS createTime, o.update_time AS updateTime, o.remark, u.user_name AS userName, u.phonenumber FROM furniture_recharge_order o LEFT JOIN sys_user u ON o.user_id = u.user_id
AND o.order_no = #{orderNo}
AND o.user_id = #{userId}
AND o.package_id = #{packageId}
AND o.pay_status = #{payStatus}
ORDER BY o.id DESC
